UPDATE companies SET description='Ohana Fiber Mill operates in Honokaa on the island of Hawaii. The business was started by Alisha and Chris after they made the Big Island their home, driven by a love for the land and a desire to turn local wool into sustainable fiber. No founding year is publicly disclosed.

The mill provides custom fiber processing for customers who supply their own wool, and it produces 100% Hawaiian-grown and processed yarn. It sources Merino, Romney, and other fibers from Kahua Ranch and other small local producers, handling the full wool-to-skein process in a historic, cozy facility. Handmade items are also sold through an on-site retail store.

The company serves local wool producers, fiber artists, makers, and the broader community.

Ohana Fiber Mill was founded to keep Hawaii''s fiber story alive by building a sustainable network connecting land, animals, and people. The founders emphasize connection to the land and the craft community as their guiding purpose.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom fiber processing", "Yarn spinning and blending", "Handmade fiber product fabrication", "Retail store operation", "Wool-to-skein processing"], "industries": ["Wool production", "Fiber arts", "Textile manufacturing", "Retail"], "materials": ["Merino wool", "Romney wool", "Hawaiian wool"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Custom fiber processing from customer-supplied wool", "100% Hawaiian-grown and processed yarn", "Direct partnerships with local ranches such as Kahua Ranch", "Historic mill space serving as a community gathering place"], "facts_used": ["Location: Honokaa, Hawaii -> db", "Founders: Alisha and Chris -> /about", "Custom fiber processing from provided fiber -> /", "100% Hawaiian grown and processed yarn -> /", "Hand made items in retail store -> /", "Work with local wool producers like Kahua Ranch -> /about", "Merino, Romney fibers sourced from Kahua Ranch -> /about", "Historic mill space -> /about", "Connection to land, animals, people -> /about", "Gathering place -> /", "Wool to skein process -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We make quality fiber from local Hawaiian wool, keeping production close to home and connected to the land.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='ohana-fiber-mill' AND approved AND profile IS NULL;
UPDATE companies SET description='Ohio Semitronics, Inc. was founded in 1964 in Hilliard, Ohio, where it pioneered the first Hall Effect electrical measurement devices. The company has remained a U.S.-based manufacturer of custom transducers and sensors for over six decades.

The company designs and builds a broad line of standard transducers — including AC/DC current, AC/DC voltage, watt-VAR, multifunction, frequency, and power factor models — as well as signal conditioners, relays, integrators, and panel meters. Its core business is custom engineering: Ohio Semitronics takes measurement concepts from discussion to working prototype in two to six weeks, leveraging CAD and 3D printing to accelerate development.

Its devices serve petroleum and petrochemical plants, electric utilities, solar and wind installations, test and measurement labs, automation and control systems, and naval surface and subsurface programs. The company has been a key resource for organizations such as Battelle Institute, Bell Labs, and the U.S. Department of Defense.

